WITH metrics AS (SELECT id, store_id, order_date, status, channel, shipping_fee, ROW_NUMBER() OVER (ORDER BY amount, id) AS event_seq, CORR(shipping_fee, amount) OVER (PARTITION BY channel) AS corr_shipping_fee_amount, CORR(shipping_fee, amount) OVER (PARTITION BY MONTH(order_date), channel) AS corr_shipping_fee_amount_2 FROM orders WHERE store_id IS NOT NULL) SELECT s.id, s.store_id, s.order_date, s.shipping_fee, s.event_seq, s.corr_shipping_fee_amount_2, (SELECT AVG(o2.discount) FROM orders o2 WHERE o2.store_id = s.store_id) AS avg_order_discount FROM metrics s
